import java.util.Random;

public class RandomWalker {

    public static int walk(long seed, int steps) {
        Random random = new Random(seed);
        int position = 0;
        for (int i = 0; i < steps; i++) {
            if (random.nextBoolean()) {
                position++;
            } else {
                position--;
            }
        }
        return position;
    }
}
